CREATE TABLE api_keys ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, scope VARCHAR(8) NOT NULL, token_hash VARCHAR(64) NOT NULL, prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, expires_at DATETIME, blocked_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE auth_sessions ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, account_id INTEGER NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, last_seen_at DATETIME NOT NULL, ip VARCHAR(64) NOT NULL, user_agent VARCHAR(255) NOT NULL, uid VARCHAR(32) DEFAULT '' NOT NULL, remember BOOLEAN DEFAULT 1 NOT NULL, stage VARCHAR(8) DEFAULT 'full' NOT NULL, second_factor_by_provider BOOLEAN DEFAULT 0 NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE counters ( name VARCHAR(32) NOT NULL, value INTEGER NOT NULL, PRIMARY KEY (name) );
CREATE TABLE deadline_snoozes ( id INTEGER NOT NULL, date_id INTEGER NOT NULL, user_id INTEGER NOT NULL, until DATE NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), CONSTRAINT uq_deadline_snoozes UNIQUE (date_id, user_id), FOREIGN KEY(date_id) REFERENCES document_dates (id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE devices ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, account_id INTEGER NOT NULL, name VARCHAR(80) NOT NULL, token_hash VARCHAR(64) NOT NULL, prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, revoked_at DATETIME, via VARCHAR(40) DEFAULT 'token' NOT NULL, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE VIRTUAL TABLE doc_fts USING fts5(title, sender, text, notes, tags, scope, tokenize = 'unicode61 remove_diacritics 2', content = '', contentless_delete = 1);
CREATE VIRTUAL TABLE doc_tri USING fts5(title, sender, text, notes, tags, scope, tokenize = 'trigram remove_diacritics 1', content = '', contentless_delete = 1);
CREATE TABLE document_dates ( id INTEGER NOT NULL, document_id INTEGER NOT NULL, kind VARCHAR(16) NOT NULL, date DATE NOT NULL, notice_n INTEGER, notice_unit VARCHAR(8), renew_months INTEGER, notice_date DATE, done_at DATETIME, done_by INTEGER, renewed_from DATE, PRIMARY KEY (id), CONSTRAINT uq_document_dates_kind UNIQUE (document_id, kind), FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, FOREIGN KEY(done_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE document_tags ( document_id INTEGER NOT NULL, tag_id INTEGER NOT NULL, PRIMARY KEY (document_id, tag_id), FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, FOREIGN KEY(tag_id) REFERENCES tags (id) ON DELETE CASCADE );
CREATE TABLE documents ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, vault_id INTEGER NOT NULL, owner_id INTEGER, title VARCHAR(200) NOT NULL, sender_id INTEGER, kind_id INTEGER, date DATE, amount INTEGER, currency VARCHAR(3) DEFAULT 'EUR' NOT NULL, status VARCHAR(12) NOT NULL, source VARCHAR(16) NOT NULL, added_at DATETIME NOT NULL, pages INTEGER NOT NULL, current_version INTEGER NOT NULL, suggest JSON, trashed_at DATETIME, trashed_status VARCHAR(12) DEFAULT '' NOT NULL, change_seq INTEGER NOT NULL, duplicate_of INTEGER, duplicate_kind VARCHAR(8) DEFAULT '' NOT NULL, process_error VARCHAR(24) DEFAULT '' NOT NULL, files_state VARCHAR(8) DEFAULT '' NOT NULL, FOREIGN KEY(vault_id) REFERENCES vaults (id) ON DELETE RESTRICT, FOREIGN KEY(owner_id) REFERENCES users (id) ON DELETE SET NULL, FOREIGN KEY(sender_id) REFERENCES senders (id) ON DELETE SET NULL, FOREIGN KEY(kind_id) REFERENCES kinds (id) ON DELETE SET NULL );
CREATE TABLE einvoices ( version_id INTEGER NOT NULL, document_id INTEGER NOT NULL, format VARCHAR(40) NOT NULL, number VARCHAR(100) NOT NULL, issued DATE, due DATE, seller VARCHAR(200) NOT NULL, seller_vat VARCHAR(40) NOT NULL, buyer VARCHAR(200) NOT NULL, buyer_ref VARCHAR(100) NOT NULL, iban VARCHAR(40) NOT NULL, currency VARCHAR(3) NOT NULL, net INTEGER, tax INTEGER, gross INTEGER, payable INTEGER, credit_note BOOLEAN NOT NULL, lines JSON, xml BLOB, created_at DATETIME NOT NULL, PRIMARY KEY (version_id), FOREIGN KEY(version_id) REFERENCES versions (id) ON DELETE CASCADE, FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE );
CREATE TABLE email_confirmations ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, address VARCHAR(255) NOT NULL, token_hash VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (account_id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE events ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, document_id INTEGER NOT NULL, user_id INTEGER, by_link VARCHAR(100) DEFAULT '' NOT NULL, at DATETIME NOT NULL, action VARCHAR(24) NOT NULL, detail JSON, FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE export_links ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, export_id INTEGER NOT NULL, recipient VARCHAR(100) NOT NULL, token_hash VARCHAR(64) NOT NULL, token_enc VARCHAR(400) NOT NULL, until DATETIME NOT NULL, opened_count INTEGER NOT NULL, last_opened_at DATETIME, created_by INTEGER, created_at DATETIME NOT NULL, revoked_at DATETIME, FOREIGN KEY(export_id) REFERENCES exports (id) ON DELETE CASCADE, UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE exports ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, state VARCHAR(10) NOT NULL, params JSON, vault_ids JSON, language VARCHAR(8) NOT NULL, documents INTEGER NOT NULL, size INTEGER NOT NULL, total INTEGER NOT NULL, file VARCHAR(80) NOT NULL, error VARCHAR(40) NOT NULL, created_at DATETIME NOT NULL, finished_at DATETIME, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE intake_items ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, document_id INTEGER, source VARCHAR(8) NOT NULL, "key" VARCHAR(600) NOT NULL, state VARCHAR(8) NOT NULL, sha256 VARCHAR(64) NOT NULL, size INTEGER NOT NULL, mtime_ns INTEGER NOT NULL, message VARCHAR(64) NOT NULL, unknown BOOLEAN NOT NULL, detail JSON, at DATETIME NOT NULL, FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE SET NULL );
CREATE TABLE invites ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, email VARCHAR(255) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE jobs ( id INTEGER NOT NULL, kind VARCHAR(16) NOT NULL, ref INTEGER NOT NULL, payload JSON, state VARCHAR(8) NOT NULL, attempts INTEGER NOT NULL, created_at DATETIME NOT NULL, started_at DATETIME, finished_at DATETIME, error VARCHAR(300) DEFAULT '' NOT NULL, PRIMARY KEY (id) );
CREATE TABLE kinds ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "key" VARCHAR(32) NOT NULL, name VARCHAR(60) NOT NULL, name_key VARCHAR(160) NOT NULL, hue INTEGER NOT NULL, position INTEGER NOT NULL, vault_id INTEGER, created_by INTEGER, FOREIGN KEY(vault_id) REFERENCES vaults (id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE links ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, document_id INTEGER NOT NULL, recipient VARCHAR(100) NOT NULL, token_hash VARCHAR(64) NOT NULL, token_enc VARCHAR(400) DEFAULT '' NOT NULL, until DATETIME NOT NULL, allow_download BOOLEAN DEFAULT 1 NOT NULL, opened_count INTEGER NOT NULL, last_opened_at DATETIME, created_by INTEGER, created_at DATETIME NOT NULL, revoked_at DATETIME, FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE mail_senders ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, address VARCHAR(255) NOT NULL, address_key VARCHAR(255) NOT NULL, token_hash VARCHAR(64) NOT NULL, expires_at DATETIME, confirmed_at DATETIME, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE notes ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, document_id INTEGER NOT NULL, user_id INTEGER, text TEXT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME, FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE oidc_links ( id INTEGER NOT NULL, provider_id INTEGER NOT NULL, subject VARCHAR(255) NOT NULL, account_id INTEGER NOT NULL, issuer VARCHAR(500) NOT NULL, email VARCHAR(320), created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), UNIQUE (provider_id, subject), UNIQUE (provider_id, account_id), FOREIGN KEY(provider_id) REFERENCES oidc_providers (id) ON DELETE CASCADE, FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE oidc_providers ( id INTEGER NOT NULL, slug VARCHAR(40) NOT NULL, label VARCHAR(64) NOT NULL, issuer VARCHAR(500) NOT NULL, client_id VARCHAR(255) NOT NULL, client_secret_enc TEXT NOT NULL, scopes VARCHAR(500) NOT NULL, enabled BOOLEAN NOT NULL, auto_create BOOLEAN NOT NULL, trusts_second_factor BOOLEAN NOT NULL, managed VARCHAR(20) NOT NULL, position INTEGER NOT NULL, redirect_path VARCHAR(300) NOT NULL, registered_redirect VARCHAR(500) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (slug) );
CREATE TABLE pairings ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, kind VARCHAR(8) NOT NULL, code_hash VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME, device_id INTEGER, client_id VARCHAR(64) DEFAULT '' NOT NULL, redirect_uri VARCHAR(300) DEFAULT '' NOT NULL, challenge VARCHAR(128) DEFAULT '' NOT NULL, device_name VARCHAR(80) DEFAULT '' NOT NULL, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (code_hash), FOREIGN KEY(device_id) REFERENCES devices (id) ON DELETE SET NULL );
CREATE TABLE paperless_items ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, origin VARCHAR(64) NOT NULL, paperless_id INTEGER NOT NULL, document_id INTEGER, state VARCHAR(8) NOT NULL, reason VARCHAR(32) NOT NULL, inbox BOOLEAN NOT NULL, at DATETIME NOT NULL, FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE SET NULL );
CREATE TABLE passkeys ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, credential_id BLOB NOT NULL, public_key BLOB NOT NULL, sign_count INTEGER NOT NULL, name VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE password_resets ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE push_devices ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, endpoint_key VARCHAR(64) NOT NULL, content TEXT NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), CONSTRAINT uq_push_devices_uid UNIQUE (uid), CONSTRAINT uq_push_devices_user_endpoint UNIQUE (user_id, endpoint_key), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE rules ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, vault_id INTEGER, created_by INTEGER, position INTEGER NOT NULL, "on" BOOLEAN NOT NULL, hits INTEGER NOT NULL, last_hit_at DATETIME, "when" JSON NOT NULL, "then" JSON NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(vault_id) REFERENCES vaults (id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE search_entries ( document_id INTEGER NOT NULL, seq INTEGER NOT NULL, digest VARCHAR(40) NOT NULL, PRIMARY KEY (document_id), FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE );
CREATE TABLE senders ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, vault_id INTEGER NOT NULL, name VARCHAR(160) NOT NULL, "key" VARCHAR(400) NOT NULL, created_by INTEGER, FOREIGN KEY(vault_id) REFERENCES vaults (id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE settings ( "key" VARCHAR(64) NOT NULL, value JSON, PRIMARY KEY ("key") );
CREATE TABLE shares ( document_id INTEGER NOT NULL, user_id INTEGER NOT NULL, "right" VARCHAR(8) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, PRIMARY KEY (document_id, user_id), FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE tags ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, vault_id INTEGER NOT NULL, name VARCHAR(40) NOT NULL, "key" VARCHAR(120) NOT NULL, created_by INTEGER, FOREIGN KEY(vault_id) REFERENCES vaults (id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE tombstones ( seq INTEGER NOT NULL, kind VARCHAR(16) NOT NULL, document_id INTEGER, vault_id INTEGER, user_id INTEGER, at DATETIME NOT NULL, PRIMARY KEY (seq) );
CREATE TABLE uploads ( id VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, vault_id INTEGER NOT NULL, filename VARCHAR(200) NOT NULL, size INTEGER NOT NULL, sha256 VARCHAR(64) NOT NULL, received INTEGER NOT NULL, source VARCHAR(8) NOT NULL, state VARCHAR(10) NOT NULL, document_id INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, api_key_id INTEGER, target_document_id INTEGER, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(vault_id) REFERENCES vaults (id) ON DELETE CASCADE );
CREATE TABLE users ( id INTEGER NOT NULL, name VARCHAR(64) NOT NULL, display_name VARCHAR(80) NOT NULL, whats_new_seen VARCHAR(32) NOT NULL, role VARCHAR(16) NOT NULL, sign_in VARCHAR(16) NOT NULL, password_hash VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, email_confirmed_at DATETIME, email_from_provider BOOLEAN DEFAULT 0 NOT NULL, oidc_subject VARCHAR(255) NOT NULL, language VARCHAR(16) NOT NULL, profile JSON, created_at DATETIME NOT NULL, last_seen_at DATETIME, failed_logins INTEGER NOT NULL, locked_until DATETIME, blocked_at DATETIME, totp_secret_enc TEXT NOT NULL, totp_recovery TEXT NOT NULL, totp_last_step INTEGER NOT NULL, avatar BLOB, avatar_at DATETIME, signed_in_before BOOLEAN DEFAULT 0 NOT NULL, passkey_handle VARCHAR(64) DEFAULT '' NOT NULL, ai_allowed BOOLEAN DEFAULT 1 NOT NULL, PRIMARY KEY (id), UNIQUE (name) );
CREATE TABLE vault_members ( vault_id INTEGER NOT NULL, user_id INTEGER NOT NULL, "right" VARCHAR(8) NOT NULL, PRIMARY KEY (vault_id, user_id), FOREIGN KEY(vault_id) REFERENCES vaults (id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE vaults ( id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, name VARCHAR(80) NOT NULL, folder VARCHAR(64) NOT NULL, icon VARCHAR(16) NOT NULL, personal_of INTEGER, created_at DATETIME NOT NULL, created_by INTEGER, FOREIGN KEY(personal_of) REFERENCES users (id) ON DELETE RESTRICT, FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE version_info ( version_id INTEGER NOT NULL, document_id INTEGER NOT NULL, origin VARCHAR(12) NOT NULL, from_n INTEGER, state VARCHAR(12) NOT NULL, error VARCHAR(24) NOT NULL, detail JSON, blanks JSON, split_dismissed BOOLEAN NOT NULL, PRIMARY KEY (version_id), FOREIGN KEY(version_id) REFERENCES versions (id) ON DELETE CASCADE, FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE );
CREATE TABLE version_texts ( version_id INTEGER NOT NULL, document_id INTEGER NOT NULL, text TEXT NOT NULL, pages INTEGER NOT NULL, ocr_pages INTEGER NOT NULL, languages VARCHAR(64) NOT NULL, digest VARCHAR(40) NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (version_id), FOREIGN KEY(version_id) REFERENCES versions (id) ON DELETE CASCADE, FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE );
CREATE TABLE versions ( id INTEGER NOT NULL, document_id INTEGER NOT NULL, n INTEGER NOT NULL, original_path VARCHAR(600) NOT NULL, archive_path VARCHAR(600) DEFAULT '' NOT NULL, sha256 VARCHAR(64) NOT NULL, size INTEGER NOT NULL, pages INTEGER NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, note VARCHAR(200) DEFAULT '' NOT NULL, phash VARCHAR(256) DEFAULT '' NOT NULL, archive_sha256 VARCHAR(64) DEFAULT '' NOT NULL, PRIMARY KEY (id), CONSTRAINT uq_versions_n UNIQUE (document_id, n), FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE INDEX ix_api_keys_account_id ON api_keys (account_id);
CREATE INDEX ix_auth_sessions_account_id ON auth_sessions (account_id);
CREATE INDEX ix_deadline_snoozes_user_id ON deadline_snoozes (user_id);
CREATE INDEX ix_devices_account_id ON devices (account_id);
CREATE INDEX ix_document_dates_document_id ON document_dates (document_id);
CREATE INDEX ix_document_tags_tag_id ON document_tags (tag_id);
CREATE INDEX ix_documents_change_seq ON documents (change_seq);
CREATE INDEX ix_documents_trashed ON documents (trashed_at);
CREATE INDEX ix_documents_vault_status ON documents (vault_id, status);
CREATE INDEX ix_einvoices_document_id ON einvoices (document_id);
CREATE INDEX ix_events_document ON events (document_id, id);
CREATE INDEX ix_export_links_export ON export_links (export_id);
CREATE INDEX ix_exports_user ON exports (user_id, state);
CREATE INDEX ix_intake_items_document ON intake_items (document_id);
CREATE INDEX ix_intake_items_message ON intake_items (message);
CREATE INDEX ix_jobs_state ON jobs (state, id);
CREATE INDEX ix_links_document_id ON links (document_id);
CREATE INDEX ix_mail_senders_key ON mail_senders (address_key);
CREATE INDEX ix_notes_document_id ON notes (document_id);
CREATE INDEX ix_oidc_links_account_id ON oidc_links (account_id);
CREATE INDEX ix_oidc_links_provider_id ON oidc_links (provider_id);
CREATE INDEX ix_pairings_account ON pairings (account_id, kind);
CREATE INDEX ix_paperless_items_document ON paperless_items (document_id);
CREATE INDEX ix_passkeys_user_id ON passkeys (user_id);
CREATE INDEX ix_password_resets_account_id ON password_resets (account_id);
CREATE INDEX ix_push_devices_user_id ON push_devices (user_id);
CREATE INDEX ix_rules_vault ON rules (vault_id, position);
CREATE INDEX ix_shares_user_id ON shares (user_id);
CREATE INDEX ix_tombstones_at ON tombstones (at);
CREATE INDEX ix_tombstones_user ON tombstones (user_id);
CREATE INDEX ix_tombstones_vault ON tombstones (vault_id);
CREATE INDEX ix_uploads_user ON uploads (user_id, state);
CREATE INDEX ix_vault_members_user_id ON vault_members (user_id);
CREATE INDEX ix_version_info_document ON version_info (document_id, state);
CREATE INDEX ix_version_texts_document_id ON version_texts (document_id);
CREATE INDEX ix_versions_sha256 ON versions (sha256);
CREATE UNIQUE INDEX uq_auth_sessions_uid ON auth_sessions (uid);
CREATE UNIQUE INDEX uq_devices_uid ON devices (uid);
CREATE UNIQUE INDEX uq_intake_items_mail ON intake_items ("key") WHERE source = 'mail';
CREATE UNIQUE INDEX uq_intake_items_taken ON intake_items (source, "key") WHERE state = 'taken';
CREATE UNIQUE INDEX uq_jobs_waiting ON jobs (kind, ref) WHERE state = 'queued';
CREATE UNIQUE INDEX uq_kinds_server ON kinds (name_key) WHERE vault_id IS NULL;
CREATE UNIQUE INDEX uq_kinds_vault ON kinds (vault_id, name_key) WHERE vault_id IS NOT NULL;
CREATE UNIQUE INDEX uq_mail_senders_user_key ON mail_senders (user_id, address_key);
CREATE UNIQUE INDEX uq_paperless_items_origin ON paperless_items (origin, paperless_id);
CREATE UNIQUE INDEX uq_passkeys_credential ON passkeys (credential_id);
CREATE UNIQUE INDEX uq_passkeys_uid ON passkeys (uid);
CREATE UNIQUE INDEX uq_senders_key ON senders (vault_id, "key");
CREATE UNIQUE INDEX uq_tags_key ON tags (vault_id, "key");
CREATE UNIQUE INDEX uq_vaults_folder ON vaults (lower(folder));
CREATE UNIQUE INDEX uq_vaults_personal ON vaults (personal_of);
CREATE UNIQUE INDEX uq_versions_original ON versions (lower(original_path));
CREATE TRIGGER documents_search_gone AFTER DELETE ON documents BEGIN DELETE FROM doc_fts WHERE rowid = old.id; DELETE FROM doc_tri WHERE rowid = old.id; END;
